    "model_answer": [
      "전반감사전략과 세부적인 감사계획은 반드시 개별적이거나 순차적인 과정으로 수립할 필요는 없다. 한쪽이 변경되면 다른 쪽도 변경될 수 있으므로 서로 밀접하게 관련되어 있기 때문이다."
    ],
    "criteria": [
      {
        "criterion_id": "crit1",
        "claim": "전반감사전략과 감사계획은 반드시 순차적일 필요가 없음을 명시함",
        "critical_facts": [
          {
            "id": "cf1",
